(() => {
 const get=id=>document.getElementById(id);let hooks={},state,devices=[],changing=false,selected={camera:'',microphone:'',speaker:'',quality:'hd'};
 try{const saved=JSON.parse(localStorage.getItem('aulaDevices')||'{}');for(const key of Object.keys(selected))if(typeof saved[key]==='string')selected[key]=saved[key];}catch{}
 const button=document.createElement('button');button.id='meetingDevices';button.type='button';button.textContent='Áudio e vídeo';button.hidden=true;document.querySelector('.room-actions').append(button);
 const dialog=document.createElement('dialog');dialog.id='deviceDialog';dialog.innerHTML='<div class="settings-heading"><h2>Áudio e vídeo</h2><button type="button" id="closeDevices" aria-label="Fechar ajustes">×</button></div><p>Escolha a câmera e o microfone que você quer usar nesta aula.</p><label>Câmera<select id="cameraDevice"></select></label><label>Qualidade da câmera<select id="cameraQuality"><option value="hd">HD · automático</option><option value="fullhd">Full HD · mais detalhes</option></select></label><label>Microfone<select id="microphoneDevice"></select></label><label id="speakerDeviceLabel">Saída de áudio<select id="speakerDevice"></select></label><p id="deviceStatus" role="status"></p><p id="deviceQuality" class="settings-help"></p><button type="button" id="refreshDevices">Atualizar dispositivos</button>';document.body.append(dialog);
 const persist=()=>{try{localStorage.setItem('aulaDevices',JSON.stringify(selected));}catch{}};
 function fill(kind,mediaKind){const node=get(kind+'Device'),old=selected[kind];node.replaceChildren();const base=document.createElement('option');base.value='';base.textContent='Padrão do sistema';node.append(base);let count=0;for(const d of devices.filter(d=>d.kind===mediaKind&&d.deviceId&&d.deviceId!=='default'&&d.deviceId!=='communications')){const option=document.createElement('option');option.value=d.deviceId;option.textContent=d.label||(kind==='camera'?'Câmera ':kind==='microphone'?'Microfone ':'Saída ')+(++count);node.append(option);}if(old&&!devices.some(d=>d.deviceId===old&&d.kind===mediaKind)){const missing=document.createElement('option');missing.value=old;missing.textContent='Dispositivo salvo indisponível';node.append(missing);}node.value=old;}
 async function refresh(){if(!navigator.mediaDevices?.enumerateDevices)return;try{devices=await navigator.mediaDevices.enumerateDevices();fill('camera','videoinput');fill('microphone','audioinput');fill('speaker','audiooutput');get('cameraQuality').value=selected.quality==='fullhd'?'fullhd':'hd';get('speakerDeviceLabel').hidden=!('setSinkId' in HTMLMediaElement.prototype);if(!devices.some(d=>d.label))get('deviceStatus').textContent='Os nomes aparecem depois de permitir a câmera ou o microfone.';}catch{get('deviceStatus').textContent='Não foi possível listar os dispositivos. Verifique a permissão do navegador.';}}
 async function change(kind,next){if(changing)return;changing=true;const old=selected[kind];for(const node of dialog.querySelectorAll('select,button'))node.disabled=true;get('deviceStatus').textContent='Aplicando sua escolha…';try{await hooks.settled?.(kind==='quality'?'camera':kind);}catch{}const active=hooks.active?.(kind==='quality'?'camera':kind);selected[kind]=next;persist();try{await (kind==='camera'||kind==='quality'?hooks.camera:kind==='microphone'?hooks.microphone:hooks.speaker)?.(active);get('deviceStatus').textContent=active?'Dispositivo atualizado.':'Escolha salva. Ligue o dispositivo para usar.';await refresh();}catch(error){selected[kind]=old;persist();let restored=true;try{await (kind==='camera'||kind==='quality'?hooks.camera:kind==='microphone'?hooks.microphone:hooks.speaker)?.(active);}catch{restored=false;}await refresh();get('deviceStatus').textContent=(error.message||'Não foi possível usar este dispositivo.')+(restored?' A escolha anterior foi restaurada.':' A escolha anterior também não pôde ser aberta. Selecione outro dispositivo.');}finally{changing=false;for(const node of dialog.querySelectorAll('select,button'))node.disabled=false;}}
 for(const kind of ['camera','microphone','speaker'])get(kind+'Device').onchange=e=>change(kind,e.target.value);get('cameraQuality').onchange=e=>change('quality',e.target.value);get('refreshDevices').onclick=refresh;get('closeDevices').onclick=()=>dialog.close();button.onclick=async()=>{dialog.showModal();await refresh();};navigator.mediaDevices?.addEventListener?.('devicechange',refresh);
 const withId=(kind,base)=>selected[kind]?{...base,deviceId:{exact:selected[kind]}}:base;
 window.meetingDevices={configure:value=>hooks=value,sync(value,stream){state=value;button.hidden=!state||state.you.status!=='accepted'||state.ended;const settings=stream?.getVideoTracks()[0]?.getSettings?.();get('deviceQuality').textContent=settings?.width?'Câmera em '+settings.width+' × '+settings.height+(settings.frameRate?' · '+Math.round(settings.frameRate)+' fps':'')+'. A qualidade recebida também depende da conexão.':'HD e Full HD dependem da câmera e do dispositivo.';},videoConstraints:()=>withId('camera',{width:{ideal:selected.quality==='fullhd'?1920:1280},height:{ideal:selected.quality==='fullhd'?1080:720}}),audioConstraints:()=>withId('microphone',{echoCancellation:true,noiseSuppression:true}),fallbackVideo:()=>selected.camera?{deviceId:{exact:selected.camera}}:true,refresh,async applyOutput(audio){if(audio?.setSinkId)await audio.setSinkId(selected.speaker||'');},close:()=>dialog.close()};
})();
